from unittest.mock import patch, Mock
import router
import service
from models import PayloadError
from routing import validation, handlers

# Original implementation, retained in memory only as a regression oracle.
def original(command, payload):
    if command not in ('create', 'update', 'delete'):
        raise ValueError('unknown command: ' + command)
    if not isinstance(payload, dict):
        raise PayloadError('payload must be a dictionary')
    normalized = {}
    if command in ('update', 'delete'):
        identifier = payload.get('id')
        if type(identifier) is not int or identifier <= 0:
            raise PayloadError('id must be positive integer')
        normalized['id'] = identifier
    if command in ('create', 'update'):
        name = payload.get('name')
        if not isinstance(name, str) or not name.strip():
            raise PayloadError('name must be nonempty string')
        normalized['name'] = name.strip()
    if command == 'create':
        return service.create(normalized['name'])
    if command == 'update':
        return service.update(normalized['id'], normalized['name'])
    return service.delete(normalized['id'])

def outcome(fn, command, payload):
    try:
        return ('result', fn(command, payload))
    except Exception as exc:
        return ('error', type(exc), str(exc))

payloads = [None, [], '', 0, {}, {'name': ' A '}, {'id': 1}, {'id': 0, 'name': ''}]
for identifier in (None, False, True, -1, 0, 1, 3, 1.0, '1'):
    for name in (None, False, 1, '', ' ', '\t B \n'):
        payloads.append({'id': identifier, 'name': name, 'extra': 'preserved'})
count = 0
for command in ('create', 'update', 'delete', 'unknown', '', None, 1, [], {}):
    for payload in payloads:
        before = payload.copy() if isinstance(payload, dict) else payload
        assert outcome(router.dispatch, command, payload) == outcome(original, command, payload)
        assert payload == before
        count += 1

for command, payload in [('create', {'name': ' A '}), ('update', {'id': 2, 'name': ' B '}), ('delete', {'id': 3})]:
    normalized = validation.validate_payload(command, payload)
    assert normalized is not payload
    handler_name = 'handle_' + command
    events = Mock()
    with patch.object(validation, 'validate_payload', wraps=validation.validate_payload) as validate, patch.object(handlers, handler_name, wraps=getattr(handlers, handler_name)) as handle:
        events.attach_mock(validate, 'validate')
        events.attach_mock(handle, 'handle')
        router.dispatch(command, payload)
        validate.assert_called_once_with(command, payload)
        handle.assert_called_once_with(normalized)
        assert [call[0] for call in events.mock_calls] == ['validate', 'handle']
    with patch.object(service, command, return_value=object()) as call:
        result = getattr(handlers, handler_name)(normalized)
        assert result is call.return_value
        args = {'create': (normalized.get('name'),), 'update': (normalized.get('id'), normalized.get('name')), 'delete': (normalized.get('id'),)}[command]
        call.assert_called_once_with(*args)

with patch.object(validation, 'validate_payload', side_effect=PayloadError('stop')) as validate, patch.object(handlers, 'handle_create') as handle:
    assert outcome(router.dispatch, 'create', {}) == ('error', PayloadError, 'stop')
    validate.assert_called_once_with('create', {})
    handle.assert_not_called()
print(f'Regression: {count} cases passed; direct handler and validation/delegation checks passed.')
